"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command "@'
const { chromium } = require('C:\\\\Users\\\\gosts\\\\AppData\\\\Roaming\\\\npm\\\\node_modules\\\\playwright');
(async()=>{
 const ids=['CH06-L01-S01','CH06-L02-S01','CH06-L02-S02','CH06-L03-S01','CH06-L03-S02','CH06-L04-S01','CH06-L04-S02','CH06-L04-S03','CH06-L04-S04','CH06-L05-S01','CH06-L05-S02','CH06-L06-S01'];
 const browser=await chromium.launch({headless:true});
 for(const id of ids){
   const p=await browser.newPage({viewport:{width:1280,height:900}});
   const errs=[]; p.on('pageerror',e=>errs.push('page:'+e.message)); p.on('console',m=>{if(m.type()==='error')errs.push('console:'+m.text())}); p.on('requestfailed',r=>errs.push('request:'+r.url()));
   const resp=await p.goto('http://localhost:8141/embeds/abap/'+id+'.html',{waitUntil:'networkidle'});
   const before=await p.evaluate(()=>({title:document.title,text:document.body.innerText.length,w:document.documentElement.scrollWidth,h:document.documentElement.scrollHeight,buttons:[...document.querySelectorAll('button')].map(x=>({t:x.innerText,d:x.disabled}))}));
   let action='';
   if(await p.locator('[data-start]').count()){
     await p.locator('[data-start]').click();
     let n=0;
     while(n<100 && await p.locator('[data-next]:not([disabled])').count()){await p.locator('[data-next]').click();n++;}
     action='step:'+n+' counter:'+(await p.locator('[data-counter]').innerText());
   } else if(await p.locator('.mk').count()){
     const n=await p.locator('.mk').count(); for(let i=0;i<n;i++) await p.locator('.mk').nth(i).click(); action='mk:'+n;
   } else if(await p.locator('#list button').count()){
     const qs=await p.locator('#list').locator('button').count();
     for(let i=0;i<qs;i+=2) await p.locator('#list').locator('button').nth(i).click();
     action='quizbuttons:'+qs+' result:'+(await p.locator('#result').innerText());
   } else if(await p.locator('#card button').count()){
     await p.locator('#card button').first().click(); action='tree';
   } else action='static';
   const after=await p.evaluate(()=>({w:document.documentElement.scrollWidth,h:document.documentElement.scrollHeight,body:document.body.innerText.slice(-300)}));
   console.log(JSON.stringify({id,status:resp&&resp.status(),before,action,after,errs}));
   await p.close();
 }
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
